@using sv_f6033dd4c28749f98358e69d02f5a844
@inject ISettingsService SettingsService

<div class="profile-section">
    @if (_loading)
    {
        <div class="text-center py-5">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (_profile is not null)
    {
        <h4 class="mb-4">Profile Settings</h4>

        @if (_successMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_successMessage
                <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label">Display Name</label>
                    <input type="text" class="form-control" @bind="_editDisplayName" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="_editEmail" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Bio</label>
                    <textarea class="form-control" rows="4" @bind="_editBio"></textarea>
                </div>
            </div>

            <div class="col-md-4">
                <div class="text-center">
                    <label class="form-label">Avatar Preview</label>
                    <div class="avatar-preview mb-2">
                        @if (!string.IsNullOrWhiteSpace(_profile.AvatarUrl))
                        {
                            <img src="@_profile.AvatarUrl" alt="Avatar" class="rounded-circle" />
                        }
                        else
                        {
                            <div class="avatar-placeholder rounded-circle">👤</div>
                        }
                    </div>
                    <small class="text-muted text-break">@_profile.AvatarUrl</small>
                </div>
            </div>
        </div>

        <div class="d-flex gap-2 mt-3">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@(!HasChanges)">
                Discard Changes
            </button>
        </div>
    }
</div>

@code {
    private UserProfile? _profile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editBio = "";
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private bool HasChanges =>
        _profile is not null &&
        (_editDisplayName != _profile.DisplayName ||
         _editEmail != _profile.Email ||
         _editBio != _profile.Bio);

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        PopulateForm();
        _loading = false;
    }

    private void PopulateForm()
    {
        if (_profile is null) return;
        _editDisplayName = _profile.DisplayName;
        _editEmail = _profile.Email;
        _editBio = _profile.Bio;
    }

    private void DiscardChanges() => PopulateForm();

    private async Task SaveAsync()
    {
        if (_profile is null) return;
        _saving = true;
        var updated = _profile with
        {
            DisplayName = _editDisplayName,
            Email = _editEmail,
            Bio = _editBio
        };
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _successMessage = "Profile saved successfully!";
        _saving = false;
    }
}

